begin;
create table public.loan_products (
    id bigint generated by default as identity primary key,
    created_at timestamptz not null default now(),
    name text default 'none',
    sort_order integer default 0,
    active boolean default true
);
create table public.loan_fields (
    id bigint generated by default as identity primary key,
    created_at timestamptz not null default now(),
    product text default '',
    sort_order integer,
    label text default '',
    type text default 'input',
    formula text default '',
    default_value numeric
);
alter table public.loan_products enable row level security;
alter table public.loan_fields enable row level security;
create policy "Enable read access for all users" on public.loan_products for select using (true);
create policy "Enable read access for all users" on public.loan_fields for select using (true);
revoke insert, update, delete, truncate, references, trigger on public.loan_products, public.loan_fields from anon, authenticated;
grant select on public.loan_products, public.loan_fields to anon, authenticated;



select setval(pg_get_serial_sequence('public.loan_products', 'id'), (select max(id) from public.loan_products));
select setval(pg_get_serial_sequence('public.loan_fields', 'id'), (select max(id) from public.loan_fields));
commit;
